// Demo-Datensatz für den Vogelstimmen-Trainer Prototyp.
// Häufigkeit und Schwierigkeit sind weiterhin erste Einschätzungen (nicht aus
// echten Monitoringdaten). Gebietsvorkommen ("areas") stammen seit dem
// eBird-Artenabgleich (ebird-artenabgleich-tool.html, Stand s. Datum unten)
// aus echten eBird-Hotspot-Meldungen im jeweils gebietsangepassten
// Suchradius um die amtlichen Gebietsgrenzen – kein Habitat-Ratespiel mehr.
// Wichtig: eBird-Hotspot-Artenlisten sind KUMULATIV (jemals dort gemeldet),
// keine aktuelle Bestandsaufnahme – Einzelbeobachtungen/Durchzügler können
// eine Art als "vorkommend" erscheinen lassen, auch wenn sie dort nur
// gelegentlich auftritt. Einzige manuelle Ausnahme: Auerhuhn (0 eBird-Treffer
// trotz bekannter Reliktvorkommen – s. Kommentar dort).
// Letzter eBird-Abgleich: 2026-07-23.

