// Habitat-Tags für die Validierungs-Seite (Erkennen-Modus nutzt sie nicht).
// habitat/vocalMonths-Felder, zwei unterschiedliche Quellen (Stand 2026-09-21,
// s. CLAUDE.md Abschnitt "Validierungs-Seite" für Details):
// - 46 Arten: manuell recherchierte "habitat"-Tags aus derselben Recherche wie
//   plausibility-check/species_flags.json (Grundlage für den
//   BirdNET-Plausibilitätscheck) – NUR bei diesen 46 ist "habitat" wirklich
//   befüllt (nicht-leeres Array).
// - 431 Arten insgesamt haben "vocalMonths" gesetzt: bei 424 davon automatisch
//   aus einer eBird-Bar-Chart-Exportdatei (wöchentliche wieder Meldehäufigkeit
//   für Deutschland, von der Nutzerin hochgeladen) abgeleitet – Achtung, das
//   ist "wann wird die Art überhaupt gemeldet" (Anwesenheit inkl. optischer
//   Beobachtungen), nicht zwingend "wann singt sie tatsächlich". Bei
//   ganzjährig anwesenden Arten (z.B. Kohlmeise) kommt dabei "vocalMonths:
//   null" heraus (kein Saisonalitäts-Signal) statt eines engen Gesangsfensters
//   – bewusste Vereinfachung, s. CLAUDE.md.
// habitat = Array von Tags aus dieser Liste, vocalMonths = [Start,Ende]-Monat
// (1-12) der typischen Ruf-/Gesangszeit oder null (ganzjährig/unsicher).
const HABITAT_LABELS = {
  wetland_reed: "Feuchtgebiet/Schilf",
  boreal_montane_conifer: "Boreal-montaner Nadelwald",
  farmland_open: "Offenland/Agrarland",
  offshore_coast: "Hochsee/Küste",
  alpine: "Alpin",
  water_shoreline: "Gewässer/Ufer",
  montane_mixed_forest: "Bergmischwald",
};

